package cn.studyroom;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;

/** 限制事实、状态投影与资格的唯一来源；不依赖预约服务，不从旧信用字段重新推断资格。 */
@Service
public class RestrictionPolicy {
    private final Store db;private final AuditService audit;private final ObjectMapper json;
    private static final String SELECT="SELECT r.*,COALESCE(NULLIF(c.real_name,''),c.username) AS creator_name,COALESCE(NULLIF(l.real_name,''),l.username) AS releaser_name,n.id AS notification_id,n.created_at AS notified_at,nr.id AS release_notification_id,nr.created_at AS release_notified_at,u.username,u.real_name,u.campus_id,u.role AS subject_role,u.status AS subject_status FROM restrictions r JOIN users u ON u.id=r.user_id LEFT JOIN users c ON c.id=r.creator_id LEFT JOIN users l ON l.id=r.releaser_id LEFT JOIN notifications n ON n.restriction_id=r.id AND n.type='restriction_started' LEFT JOIN notifications nr ON nr.restriction_id=r.id AND nr.type='restriction_released' ";
    public RestrictionPolicy(Store db,AuditService audit,ObjectMapper json){this.db=db;this.audit=audit;this.json=json;}
    List<Map<String,Object>> activeRaw(long user,LocalDateTime now){return db.list("SELECT * FROM restrictions WHERE user_id=? AND starts_at<=? AND ends_at>? AND released_at IS NULL ORDER BY id",user,stamp(now),stamp(now));}
    List<Long> activeUsers(LocalDateTime now){return db.list("SELECT DISTINCT user_id FROM restrictions WHERE starts_at<=? AND ends_at>? AND released_at IS NULL ORDER BY user_id",stamp(now),stamp(now)).stream().map(row->Store.id(row,"user_id")).toList();}
    List<Long> candidateUsers(LocalDateTime now){return db.list("SELECT user_id FROM restrictions WHERE starts_at<=? AND ends_at>? AND released_at IS NULL UNION SELECT v.user_id FROM violations v JOIN users u ON u.id=v.user_id WHERE u.role IN('student','staff') AND v.status='active' AND v.occurred_at>=? AND v.occurred_at<=? AND NOT EXISTS(SELECT 1 FROM restriction_evaluation_sources s WHERE s.violation_id=v.id) ORDER BY user_id",stamp(now),stamp(now),stamp(now.minusDays(30)),stamp(now)).stream().map(row->Store.id(row,"user_id")).toList();}
    /** Only actual batches are persisted; below-threshold reads never create evaluation history. */
    @Transactional(propagation=Propagation.MANDATORY)
    public Long assess(long user,LocalDateTime now){
        db.lockBookings();var account=db.one("SELECT role FROM users WHERE id=?",user);if(!AuthService.isOrdinary(account.get("role"))||!activeRaw(user,now).isEmpty())return null;
        var candidates=db.list("SELECT v.id FROM violations v WHERE v.user_id=? AND v.status='active' AND v.occurred_at>=? AND v.occurred_at<=? AND NOT EXISTS(SELECT 1 FROM restriction_evaluation_sources s WHERE s.violation_id=v.id) ORDER BY v.occurred_at,v.id LIMIT 3",user,stamp(now.minusDays(30)),stamp(now));if(candidates.size()<3)return null;
        long id=db.insert("INSERT INTO restrictions(user_id,source,starts_at,ends_at,reason,created_at) VALUES(?,'automatic',?,?,?,?)",user,stamp(now),stamp(now.plusHours(168)),"最近30天内累计三条有效且未用于既有自动限制的违规，自动限制新预约7天",stamp(now));
        db.update("INSERT INTO restriction_evaluations(restriction_id,user_id,evaluated_at,window_start,window_end) VALUES(?,?,?,?,?)",id,user,stamp(now),stamp(now.minusDays(30)),stamp(now));
        var sources=new ArrayList<Map<String,Object>>();for(int index=0;index<3;index++){long violation=Store.id(candidates.get(index),"id");var snapshot=ViolationService.safeOne(db,violation);db.update("INSERT INTO restriction_evaluation_sources(restriction_id,user_id,violation_id,source_order,violation_snapshot) VALUES(?,?,?,?,CAST(? AS JSONB))",id,user,violation,index+1,write(snapshot));sources.add(snapshot);}
        audit.record(null,"restriction.automatic_create","restriction",Long.toString(id),"按发生时刻滚动累计三条未消费有效违规，立即限制新预约168小时",Map.of(),Map.of("user_id",user,"source","automatic","evaluated_at",offset(now),"window_start",offset(now.minusDays(30)),"window_end",offset(now),"source_violation_ids",candidates.stream().map(row->row.get("id")).toList()));return id;
    }
    Map<String,Object> eligibility(long user,LocalDateTime now){var account=db.one("SELECT role,status FROM users WHERE id=?",user);var active=rows("WHERE r.user_id=? AND r.starts_at<=? AND r.ends_at>? AND r.released_at IS NULL",user,stamp(now),stamp(now)).stream().map(row->view(row,now,false)).toList();String blocked=!AuthService.isOrdinary(account.get("role"))?"role":!"active".equals(account.get("status"))?"disabled":active.isEmpty()?null:"restrictions";var result=new LinkedHashMap<String,Object>();result.put("can_book",blocked==null);result.put("blocked_by",blocked);result.put("active_restrictions",active);result.put("server_now",offset(now));result.put("campus_zone",BookingPolicy.CAMPUS_ZONE.toString());return result;}
    Map<String,Object> denial(Map<String,Object> eligibility){var result=new LinkedHashMap<String,Object>();result.put("code","booking_restricted");for(String key:List.of("active_restrictions","server_now","campus_zone"))result.put(key,eligibility.get(key));return result;}
    boolean legacyActive(long user,LocalDateTime now){return db.count("SELECT count(*) FROM restrictions WHERE user_id=? AND source='legacy' AND released_at IS NULL AND starts_at<=? AND ends_at>?",user,stamp(now),stamp(now))>0;}
    List<Map<String,Object>> list(Long user,String status,LocalDateTime now,boolean admin){return RecordPage.items(records(RecordPage.legacy(status==null?Map.of():Map.of("status",status),RecordPage.Domain.RESTRICTION,admin),user,now,admin));}
    Map<String,Object> records(RecordPage query,Long user,LocalDateTime now,boolean admin){var selected=query.select(db,RecordPage.Domain.RESTRICTION,user,now);var result=selected.ids().isEmpty()?new ArrayList<Map<String,Object>>():rows("WHERE r.id IN ("+RecordPage.marks(selected.ids())+") ORDER BY r.created_at DESC,r.id DESC",selected.ids().toArray()).stream().map(row->view(row,now,admin)).toList();for(var item:result)for(String key:List.of("verification_note","facts_confirmed","release_verification_note","release_facts_confirmed"))item.remove(key);return query.result(result,selected.total(),now);}
    static void validateFilter(Long user,String status){Api.require(user==null||user>0,400,"用户编号须为正整数");Api.require(status==null||Set.of("active","expired","released").contains(status),400,"限制状态筛选错误");}
    Map<String,Object> required(long id){return db.one("SELECT * FROM restrictions WHERE id=?",id);}
    Map<String,Object> detail(long id,LocalDateTime now,boolean admin){return view(db.one(SELECT+" WHERE r.id=?",id),now,admin);}
    @Transactional(propagation=Propagation.MANDATORY)
    public long create(long actor,long user,LocalDateTime now,LocalDateTime end,String reason,String note){long id=db.insert("INSERT INTO restrictions(user_id,source,starts_at,ends_at,reason,creator_id,verification_note,facts_confirmed,created_at) VALUES(?,'manual',?,?,?,?,?,true,?)",user,stamp(now),stamp(end),reason,actor,note,stamp(now));audit.record(actor,"restriction.create","restriction",Long.toString(id),reason,Map.of(),Map.of("user_id",user,"source","manual","starts_at",now.toString(),"ends_at",end.toString(),"verification_source","admin_self_report","facts_confirmed",true));return id;}
    @Transactional(propagation=Propagation.MANDATORY)
    public void applied(Map<String,Object> restriction,Map<String,Object> effects,Long actor,LocalDateTime now){if(restriction.get("effects_applied_at")!=null)return;long id=Store.id(restriction,"id");int changed=db.update("UPDATE restrictions SET effects_applied_at=?,version=version+1 WHERE id=? AND effects_applied_at IS NULL",stamp(now),id);if(changed==0)return;String message=switch(Store.text(restriction,"source")){case "legacy"->"历史限制剩余有效期已接管，保留原截止；当前起点仅为余期接管时刻，原始原因与起点未可靠记录。";case "automatic"->"系统根据最近30天内三条未消费的有效违规生成7天预约限制。";default->"预约限制已生效。";};String content=message+"\n公开原因：\n"+restriction.get("reason")+"\n原定截止："+offset(restriction.get("ends_at"))+"\n当前已取消仍有效待签到预约"+((List<?>)effects.get("cancelled_pending")).size()+"条，使用中预约可继续至原定结束。";notify(Store.id(restriction,"user_id"),id,"restriction_started","预约限制已生效",content,now);audit.record(actor,"restriction.apply","restriction",Long.toString(id),"实际执行限制收敛与通知，未回写过去取消或通知时刻",Map.of(),Map.of("source",restriction.get("source"),"effects_applied_at",now.toString(),"cancelled_pending",effects.get("cancelled_pending")));}
    @Transactional(propagation=Propagation.MANDATORY)
    public void release(long actor,Map<String,Object> before,String reason,String note,LocalDateTime now){long id=Store.id(before,"id");db.update("UPDATE restrictions SET released_at=?,release_reason=?,releaser_id=?,release_verification_note=?,release_facts_confirmed=true,version=version+1 WHERE id=?",stamp(now),reason,actor,note,id);notify(Store.id(before,"user_id"),id,"restriction_released","一条预约限制已解除","此条预约限制已解除。\n解除原因：\n"+reason+"\n其他有效限制仍分别生效，是否可以新预约请查看当前资格。",now);audit.record(actor,"restriction.release","restriction",Long.toString(id),reason,Map.of("version",before.get("version"),"source",before.get("source")),Map.of("released_at",now.toString(),"version",Store.id(before,"version")+1,"verification_source","admin_self_report","facts_confirmed",true));}
    /** Pure original-batch calculation: never borrows another event or uses today's window to rewrite the old one. */
    List<Map<String,Object>> projectAppealRecalculations(long user,long violation,LocalDateTime now){
        var references=db.list("SELECT restriction_id FROM restriction_evaluation_sources WHERE violation_id=? AND user_id=?",violation,user);var results=new ArrayList<Map<String,Object>>();
        for(var reference:references){long id=Store.id(reference,"restriction_id");var batch=db.one("SELECT r.*,e.evaluated_at,e.window_start,e.window_end,e.threshold FROM restrictions r JOIN restriction_evaluations e ON e.restriction_id=r.id AND e.user_id=r.user_id WHERE r.id=? AND r.user_id=? AND r.source='automatic'",id,user);var originals=db.list("SELECT violation_id,source_order,violation_snapshot FROM restriction_evaluation_sources WHERE restriction_id=? AND user_id=? ORDER BY source_order",id,user);if(originals.size()!=3)throw new IllegalStateException("原自动限制永久来源不完整，请核查数据");
            var start=LocalDateTime.parse(Store.text(batch,"window_start"));var end=LocalDateTime.parse(Store.text(batch,"window_end"));var sources=new ArrayList<Map<String,Object>>();int before=0,after=0;
            for(int index=0;index<3;index++){var original=originals.get(index);long sourceId=Store.id(original,"violation_id");Map<String,Object> frozen;try{frozen=json.readValue(Store.text(original,"violation_snapshot"),new TypeReference<LinkedHashMap<String,Object>>(){});}catch(Exception e){throw new IllegalStateException("原自动限制来源快照无法读取，请核查数据",e);}if(Store.id(original,"source_order")!=index+1||!(frozen.get("id") instanceof Number number)||number.longValue()!=sourceId||!"active".equals(frozen.get("status"))||frozen.get("occurred_at")==null)throw new IllegalStateException("原自动限制来源快照不完整，请核查数据");
                LocalDateTime occurred=OffsetDateTime.parse(frozen.get("occurred_at").toString()).atZoneSameInstant(BookingPolicy.CAMPUS_ZONE).toLocalDateTime();if(occurred.isBefore(start)||occurred.isAfter(end))throw new IllegalStateException("原自动限制来源不属于原评估窗口，请核查数据");var source=ViolationService.safeOne(db,sourceId);if(!occurred.equals(OffsetDateTime.parse(source.get("occurred_at").toString()).atZoneSameInstant(BookingPolicy.CAMPUS_ZONE).toLocalDateTime()))throw new IllegalStateException("原违规发生时刻与固定来源矛盾，请核查数据");boolean valid="active".equals(source.get("status"));if(valid)before++;String statusAfter=sourceId==violation?"revoked":Store.text(source,"status");if("active".equals(statusAfter))after++;var item=new LinkedHashMap<String,Object>(source);item.put("status_after",statusAfter);sources.add(item);
            }
            String beforeStatus=status(batch,now),outcome=beforeStatus.equals("expired")?"expired_recorded":beforeStatus.equals("released")?"released_recorded":after<3?"released":"retained";var result=new LinkedHashMap<String,Object>();result.put("restriction_id",id);result.put("status_before",beforeStatus);result.put("status_after",outcome.equals("released")?"released":beforeStatus);result.put("outcome",outcome);result.put("valid_count_before",before);result.put("valid_count_after",after);result.put("threshold",3);for(String key:List.of("evaluated_at","window_start","window_end","starts_at","ends_at"))result.put(key,offset(batch.get(key)));result.put("source_violations",sources);results.add(result);
        }return results;
    }
    @Transactional(propagation=Propagation.MANDATORY)
    public void applyAppealRecalculations(long actor,long review,long user,long violation,List<Map<String,Object>> projections,String reason,String note,LocalDateTime now){
        db.lockBookings();for(var result:projections){long id=Store.id(result,"restriction_id");var original=required(id);if(!"automatic".equals(original.get("source"))||Store.id(original,"user_id")!=user)throw new IllegalStateException("申诉重算只允许对应原自动限制");if("released".equals(result.get("outcome"))){Api.require(activeRaw(user,now).stream().anyMatch(row->Store.id(row,"id")==id),409,"原限制状态已变化，请重新预览");release(actor,original,reason,note,now);}
            db.update("INSERT INTO restriction_recalculations(review_id,user_id,violation_id,restriction_id,status_before,status_after,outcome,valid_count_before,valid_count_after,evaluated_at,window_start,window_end,starts_at,ends_at,source_violations) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,CAST(? AS JSONB))",review,user,violation,id,result.get("status_before"),result.get("status_after"),result.get("outcome"),result.get("valid_count_before"),result.get("valid_count_after"),stamp(localOffset(result.get("evaluated_at"))),stamp(localOffset(result.get("window_start"))),stamp(localOffset(result.get("window_end"))),stamp(localOffset(result.get("starts_at"))),stamp(localOffset(result.get("ends_at"))),write(result.get("source_violations")));
            audit.record(actor,"restriction.recalculate","restriction",Long.toString(id),reason,Map.of("status",result.get("status_before"),"valid_count",result.get("valid_count_before")),Map.of("review_id",review,"outcome",result.get("outcome"),"valid_count",result.get("valid_count_after"),"original_sources_preserved",true));
        }
    }
    private static LocalDateTime localOffset(Object value){return OffsetDateTime.parse(value.toString()).atZoneSameInstant(BookingPolicy.CAMPUS_ZONE).toLocalDateTime();}
    Map<String,Object> operation(String operation){var rows=db.list("SELECT * FROM restriction_operations WHERE operation_id=CAST(? AS UUID)",operation);return rows.isEmpty()?null:rows.get(0);}
    @Transactional(propagation=Propagation.MANDATORY)
    public void saveOperation(String operation,long id,long actor,String action,String hash,Map<String,Object> effects,LocalDateTime now){db.update("INSERT INTO restriction_operations(operation_id,restriction_id,actor_id,action,request_hash,effects,created_at) VALUES(CAST(? AS UUID),?,?,?,?,CAST(? AS JSONB),?)",operation,id,actor,action,hash,write(effects),stamp(now));}
    Map<String,Object> effects(Map<String,Object> operation){try{return json.readValue(operation.get("effects").toString(),new TypeReference<LinkedHashMap<String,Object>>(){});}catch(Exception e){throw new IllegalStateException("限制执行结果无法读取",e);}}
    private List<Map<String,Object>> rows(String where,Object...args){return db.list(SELECT+where,args);}
    private Map<String,Object> view(Map<String,Object> row,LocalDateTime now,boolean admin){var result=new LinkedHashMap<String,Object>();for(String key:List.of("id","source","version","reason","effects_applied_at","released_at","release_reason","notification_id","release_notification_id"))result.put(key,row.get(key));for(String key:List.of("starts_at","ends_at","created_at","effects_applied_at","released_at","notified_at","release_notified_at"))result.put(key,offset(row.get(key)));result.put("status",status(row,now));result.put("creator_display_name",row.get("creator_name"));result.put("releaser_display_name",row.get("releaser_name"));boolean legacy="legacy".equals(row.get("source"));result.put("verification_source",legacy?"legacy_remaining_transfer":"automatic".equals(row.get("source"))?"system_rolling_violations":"admin_self_report");result.put("legacy_remaining_only",legacy);result.put("automatic_evaluation",automaticEvaluation(row));result.put("server_now",offset(now));result.put("campus_zone",BookingPolicy.CAMPUS_ZONE.toString());if(admin){var subject=new LinkedHashMap<String,Object>();subject.put("id",row.get("user_id"));for(String key:List.of("username","real_name","campus_id"))subject.put(key,row.get(key));subject.put("role",row.get("subject_role"));subject.put("status",row.get("subject_status"));result.put("subject",subject);for(String key:List.of("verification_note","facts_confirmed","release_verification_note","release_facts_confirmed"))result.put(key,row.get(key));}return result;}
    private Map<String,Object> automaticEvaluation(Map<String,Object> row){
        if(!"automatic".equals(row.get("source")))return null;long id=Store.id(row,"id");var snapshots=db.list("SELECT * FROM restriction_evaluations WHERE restriction_id=?",id);var sources=db.list("SELECT violation_id FROM restriction_evaluation_sources WHERE restriction_id=? ORDER BY source_order",id);if(snapshots.size()!=1||sources.size()!=3)throw new IllegalStateException("自动限制评估或永久来源不完整，请核查数据");
        var stored=snapshots.get(0);var result=new LinkedHashMap<String,Object>();for(String key:List.of("evaluated_at","window_start","window_end"))result.put(key,offset(stored.get(key)));for(String key:List.of("window_start_inclusive","window_end_inclusive","threshold","duration_hours"))result.put(key,stored.get(key));result.put("source_violations",sources.stream().map(source->ViolationService.safeOne(db,Store.id(source,"violation_id"))).toList());return result;
    }
    String status(Map<String,Object> row,LocalDateTime now){return row.get("released_at")!=null?"released":!now.isBefore(LocalDateTime.parse(row.get("ends_at").toString()))?"expired":"active";}
    private void notify(long user,long restriction,String type,String title,String content,LocalDateTime now){db.update("INSERT INTO notifications(user_id,type,title,content,restriction_id,created_at) VALUES(?,?,?,?,?,?)",user,type,title,content,restriction,stamp(now));}
    private String write(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
    static Timestamp stamp(LocalDateTime value){return Timestamp.valueOf(value);}
    static String offset(Object value){return value==null?null:LocalDateTime.parse(value.toString()).atZone(BookingPolicy.CAMPUS_ZONE).toOffsetDateTime().toString();}
}
